const SVC_REAL = [{"id": 41, "n": "СВКС-м", "t": "Сервис видеоконференцсвязи МВД России", "tabs": ["Описание сервиса", "Вопросы по сервису", "Развитие сервиса"], "al": ["В связи с проведением технологических работ на сервисе СУДИС в период с 23:00 17.08.2026 до 07:00 11.11.2026 (время московское) возможны перебои с доступом к сервису (Российская Федерация).", "В связи с проведением технологических работ на сервисе Подсистема ОИБ в период с 14:30 02.10.2026 до 15:30 02.10.2026 (время московское) возможны перебои с доступом к сервису (Ханты-Мансийский автономный округ - Югра)."], "d": "<p>Сервис видеоконференцсвязи МВД России (СВКС-м) – один из сервисов ИСОД, обеспечивающий коммуникацию сотрудников с использованием видеосвязи. Сервис предназначен для оптимизации и ускорения процесса получения и обработки информации при принятии управленческих решений.<br>Основные задачи СВКС-м: обеспечение оперативной связи сотрудников МВД России, сокращение командировочных и транспортных расходов, увеличение производительности труда, упрощение процедуры проведения региональных и федеральных селекторных совещаний.</p>", "reg": 1, "btn": ["Воспользоваться сервисом"], "tr": ["Курс по обучению"], "docs": [["Основные документы", [["pdf", "Инструкция по установке (новая)", "17 ноября 2021, 10:24"], ["pdf", "Руководство пользователя (новое)", "30 ноября 2021, 15:59"]]]], "resp": [["Зайцев Павел Игоревич", "ЦВЦ МВД России, Заместитель начальника 5 отдела", "8 (495) 031-02-72", "pzaitsev@mvd.ru"], ["Ершов Ярослав Алексеевич", "УИТ ДИТСиЗИ МВД России, Старший специалист по ОП отдела", "8 (495) 031-05-86", "iaershov22@mvd.ru"]], "ts": 1, "nm": "СВКС", "dx": ""}, {"id": 2, "n": "СЭД", "t": "Сервис электронного документооборота", "tabs": ["Описание сервиса", "Вопросы по сервису", "Развитие сервиса"], "al": ["В связи с проведением технологических работ на сервисе СУДИС в период с 23:00 17.08.2026 до 07:00 11.11.2026 (время московское) возможны перебои с доступом к сервису (Российская Федерация).", "В связи с проведением технологических работ на сервисе СЭД в период с 21:00 23.09.2026 до 21:00 06.10.2026 (время московское) возможны перебои с доступом к сервису (Приволжский федеральный округ).", "В связи с проведением технологических работ на сервисе СЭД в период с 21:00 29.09.2026 до 21:00 13.10.2026 (время московское) возможны перебои с доступом к сервису (Северо-Западный федеральный округ).", "В связи с проведением технологических работ на сервисе СЭД в период с 21:00 30.09.2026 до 21:00 14.10.2026 (время московское) возможны перебои с доступом к сервису (Республика Крым).", "В связи с проведением технологических работ на сервисе Подсистема ОИБ в период с 14:30 02.10.2026 до 15:30 02.10.2026 (время московское) возможны перебои с доступом к сервису (Ханты-Мансийский автономный округ - Югра)."], "d": "<p>Сервис электронного документооборота предназначен для автоматизации деятельности сотрудников федеральных государственных гражданских служащих и работников центрального аппарата МВД России, территориальных органов МВД России, а также иных организаций и подразделений, созданных для выполнения задач и осуществления полномочий, возложенных на органы внутренних дел, направленных на подготовку, обработку, хранение и использование документов (в том числе и документов в электронной форме), образующихся в ходе деятельности органов внутренних дел.</p>", "reg": 1, "wp": ["Модернизированная версия рабочего места должностного лица", "Рабочее место делопроизводителя"], "btn": ["Воспользоваться сервисом"], "docs": [["Основные документы", [["pdf", "Презентация СЭД", "27 апреля 2018, 18:29"]]], ["Последние обновленные документы", []]], "extra": ["Настройка постфиксов для существующих типов документов", "Настройка постфиксов для новых типов документов", "Переименование журнала"], "resp": [["Панфилов Тимур Юрьевич", "", "", ""]], "nm": "^СЭД$", "dx": ""}, {"id": 0, "n": "Подсистема ОИБ", "t": "Подсистема обеспечения информационной безопасности ИСОД МВД России", "tabs": ["Описание сервиса", "Вопросы по сервису", "Развитие сервиса"], "al": ["В связи с проведением технологических работ на сервисе СУДИС в период с 23:00 17.08.2026 до 07:00 11.11.2026 (время московское) возможны перебои с доступом к сервису (Российская Федерация).", "В связи с проведением технологических работ на сервисе Подсистема ОИБ в период с 14:30 02.10.2026 до 15:30 02.10.2026 (время московское) возможны перебои с доступом к сервису (Ханты-Мансийский автономный округ - Югра)."], "d": "<p>Подсистема обеспечения информационной безопасности - один из составных элементов ИСОД МВД России, целью которого является защита информации на всех этапах жизненного цикла как в целом ИСОД МВД России, так и каждого из ее элементов в отдельности.</p><p>Веб-приложение управления доступом, которое входит в состав СУДИС, предназначено для администраторов и операторов доступа ИСОД МВД России.</p>", "btn": ["Воспользоваться сервисом", "Воспользоваться веб-порталом администраторов доступа"], "tr": ["Курсы по обучению Подсистема ОИБ", "Курсы по обучению СУДИС"], "docs": [["Основные документы", [["xls", "Заявка на восстановление пароля к учетной записи", "09 марта 2016, 17:58"], ["pdf", "Памятка по информационной безопасности", "24 июня 2026, 10:53"], ["ppt", "Презентация подсистемы ОИБ", "24 июня 2026, 10:53"]]], ["Последние обновленные документы", []]], "forum": 1, "resp": [["Тарасов Станислав Игоревич", "ЦССиЗИ ФКУ \"ГИАЦ МВД России\", Специалист отдела СиА ПОИБ ИСОД МВД России", "8 (495) 031-28-56", "mkalmykov6@mvd.ru"]], "nm": "ОИБ", "dx": "информационной безопасности"}, {"id": 29, "n": "ВИСП", "t": "Ведомственный информационно-справочный портал", "tabs": ["Описание сервиса", "Вопросы по сервису", "Развитие сервиса"], "al": ["В связи с проведением технологических работ на сервисе СУДИС в период с 23:00 17.08.2026 до 07:00 11.11.2026 (время московское) возможны перебои с доступом к сервису (Российская Федерация).", "В связи с проведением технологических работ на сервисе ВИСП в период с 22:00 25.09.2026 до 21:00 02.10.2026 (время московское) возможны перебои с доступом к сервису (Российская Федерация).", "В связи с проведением технологических работ на сервисе Подсистема ОИБ в период с 14:30 02.10.2026 до 15:30 02.10.2026 (время московское) возможны перебои с доступом к сервису (Ханты-Мансийский автономный округ - Югра)."], "d": "<p>Прикладной сервис доступа к ведомственному информационно-справочному порталу (ВИСП) - прикладной сервис обеспечения повседневной деятельности подразделений МВД России, доступен для всех пользователей ИСОД МВД России.<br>ВИСП разработан как инструмент информационной поддержки эффективного управления и использования общих информационных ресурсов для сотрудников МВД России.<br>ВИСП является также инструментом формирования единого информационного пространства, структуризации и хранения ведомственной информации, совершенствования внутренних коммуникаций между сотрудниками и структурными подразделениями, снижения временных затрат на сбор, обработку и поиск информации.</p>", "tr": ["Курс по обучению"], "docs": [["Основные документы", [["doc2", "Образец заявки", "29 декабря 2025, 16:44"], ["pdf", "Описание применения", "18 сентября 2016, 22:11"], ["pdf", "Презентация сервиса ВИСП", "20 августа 2016, 22:44"], ["pdf", "Руководство оператора", "18 сентября 2016, 22:13"]]]], "resp": [["Ершов Ярослав Алексеевич", "УИТ ДИТСиЗИ МВД России, Старший специалист по ОП отдела", "8 (495) 031-05-86", "iaershov22@mvd.ru"]], "ts": 1, "nm": "^ВИСП$", "dx": ""}, {"id": 61, "n": "Интернет-сайт", "t": "Официальный интернет-сайт МВД России", "tabs": ["Описание сервиса"], "al": ["В связи с проведением технологических работ на сервисе СУДИС в период с 23:00 17.08.2026 до 07:00 11.11.2026 (время московское) возможны перебои с доступом к сервису (Российская Федерация).", "В связи с проведением технологических работ на сервисе Интернет-сайт в период с 23:00 21.09.2026 до 06:00 05.10.2026 (время московское) возможны перебои с доступом к сервису (Российская Федерация).", "В связи с проведением технологических работ на сервисе Подсистема ОИБ в период с 14:30 02.10.2026 до 15:30 02.10.2026 (время московское) возможны перебои с доступом к сервису (Ханты-Мансийский автономный округ - Югра)."], "d": "<p>Официальный интернет-сайт МВД России предназначен для предоставления пользователям сети Интернет информации о деятельности МВД России.<br>Интернет-сайт позволяет получить информацию о:</p><ul style='margin:0;padding-left:18px'><li>руководстве, структуре и деятельности МВД России;</li><li>результатах деятельности пресс-службы: новости, пресс-релизы;</li><li>документах, регламентирующих деятельность МВД России;</li><li>работе МВД России с вопросами посетителей;</li><li>отделениях полиции, участковых и т.д.</li></ul>", "btn": ["Перейти на сайт", "Воспользоваться сервисом", "Пресс-индекс", "Тестовая среда"], "docs": [["Основные документы", [["xls", "Администраторы АПК", "09 декабря 2024, 10:55"], ["xls", "Заявка на администрирование", "28 марта 2019, 13:27"], ["pdf", "Презентация сервиса Интернет-сайт", "05 сентября 2023, 16:23"], ["pdf", "Приказ №109", "21 мая 2026, 13:20"], ["pdf", "Приказ №15", "13 мая 2025, 11:56"]]]], "resp": [["Зайцева Ксения Дмитриевна", "УОС МВД России", "", ""]], "nm": "^Интернет", "dx": ""}, {"id": 233, "n": "Контроль исполнения", "t": "Сервис контроля исполнения документов, планов и поручений МВД России", "tabs": ["Описание сервиса"], "bc": 1, "d": "<p>Сервис контроля исполнения документов, планов и поручений предназначен для обеспечения деятельности подразделений и сотрудников ОАД МВД России, подразделений центрального аппарата МВД России, территориальных органов МВД России, иных организаций и подразделений, созданных для выполнения задач и осуществления полномочий, возложенных на МВД России, выполняющих функции контроля исполнения документов, планов и поручений</p>", "btn": ["Воспользоваться сервисом"], "docs": [["Последние обновленные документы", []]], "resp": [["Лаптев Тимур Игоревич", "КО КПУ ОАД МВД России, Старший инспектор по особым поручениям", "8 (495) 031-76-51", "tlaptev3@mvd.ru"], ["Устинов Ильдар Николаевич", "КО КПУ ОАД МВД России, Заместитель начальника контрольного отдела контрольно-планового управления - начальник отделения (отделение контроля внутренних поручений)", "8 (495) 031-66-79", "iustinov3@mvd.ru"]], "ts": 1, "nm": "^$", "dx": "контроля исполнения"}, {"id": 203, "n": "СОДП СБ", "t": "Сервис обеспечения деятельности подразделений собственной безопасности в области учета совершенных сотрудниками, федеральными государственными гражданскими служащими и работниками системы МВД России преступлений", "tabs": ["Описание сервиса"], "bc": 1, "d": "<p>СОДП СБ является прикладным сервисом единой системы информационно-аналитического обеспечения деятельности Министерства внутренних дел Российской Федерации и предназначен для обеспечения деятельности ГУСБ МВД России, подразделений собственной безопасности территориальных органов МВД России на окружном, межрегиональном и региональном уровнях, а также для обеспечения проведения подразделениями центрального аппарата МВД России анализа состояния законности в органах внутренних дел Российской Федерации по направлениям оперативно-служебной деятельности</p>", "btn": ["Воспользоваться сервисом"], "docs": [], "resp": [["Осипов Вадим Дмитриевич", "Старший оперуполномоченный по ОВД", "", "vosipov@mvd.ru"]], "ts": 1, "nm": "^СОДП СБ", "dx": ""}, {"id": 221, "n": "ЕАИС ЭКП", "t": "Программное обеспечение сервиса единой автоматизированной информационной системы экспертно-криминалистических подразделений МВД России «ЕАИС ЭКП» единой системы информационно-аналитического обеспечения деятельности МВД России", "tabs": ["Описание сервиса"], "d": "<p>ЕАИС ЭКП является прикладным Сервисом единой системы информационно-аналитического обеспечения деятельности Министерства внутренних дел Российской Федерации и предназначен для:<br>1. Обеспечения автоматизации учета результатов деятельности ФКУ «Экспертно-криминалистический центр МВД России», экспертно-криминалистических центров, отделов (отделений, групп) территориальных органов МВД России на окружном, межрегиональном, региональном и районном уровнях по производству судебных экспертиз по уголовным делам, делам об административных правонарушениях и материалам доследственных проверок, а также для применения технических средств и специальных знаний по заданиям уполномоченных законодательством Российской Федерации органов и должностных лиц.<br>2. Обеспечения автоматизации формирования и ведения экспертно-криминалистических учетов в системе МВД России на федеральном, региональном и районном уровнях.<br>3. Обеспечения автоматизации деятельности экспертно-квалификационных комиссий, в том числе центральной экспертно-квалификационной комиссии.<br>4. Обеспечения автоматизации учета информации об огнестрельном оружии и патронах в криминалистических коллекциях ЭКЦ МВД России и ЭКП территориальных органов МВД России.<br>5. Обеспечения автоматизации кадрового учета ЭКП.<br>6. Организационно-методического обеспечения деятельности ЭКП.<br>7. Обеспечения автоматизации и оптимизации подготовки ведомственной статистической отчетности.<br>8. Создания единой базы экспертно-криминалистических материалов, публикаций и знаний.</p>", "btn": ["Воспользоваться сервисом"], "docs": [["Основные документы", [["doc2", "Образец заявки ЕАИС ЭКП", "11 августа 2026, 18:45"]]]], "resp": [["Денисов Тимур Алексеевич", "КПО ОМУ ЭКЦ МВД России, Старший эксперт", "8 (499) 745-79-16", "tdenisov6@mvd.ru"]], "ts": 1, "nm": "^ЕАИС", "dx": ""}, {"id": 227, "n": "Ситуационный центр", "t": "Сервис информационно-аналитического обеспечения деятельности Ситуационного центра Министерства внутренних дел Российской Федерации", "tabs": ["Описание сервиса"], "bc": 1, "d": "<p>Сервис предназначен для повышения качества и оперативности обработки информации в целях оценки, анализа и моделирования ситуаций в сфере противодействия преступности, охраны общественного порядка и обеспечения общественной безопасности в условиях обострения оперативной обстановки, а также всесторонней поддержки принятия решений органами оперативного управления силами и средствами МВД России при возникновении чрезвычайных обстоятельств (ситуаций) на основании прогнозов, геопространственного анализа и моделирования вариантов развития ситуации.</p>", "btn": ["Воспользоваться сервисом"], "resp": [["Белкин Ильдар Викторович", "Отдел \"И\" ЦОР МВД России, Старший инспектор по особым поручениям", "8 (495) 031-64-44", "dsopin@mvd.ru"]], "ts": 1, "nodocs": 1, "nm": "^$", "dx": "Ситуационн"}, {"id": 182, "n": "Контроль за оборотом наркотиков", "t": "Сервис обеспечения деятельности подразделений по контролю за оборотом наркотиков", "tabs": ["Описание сервиса"], "al": ["В связи с проведением технологических работ на сервисе СУДИС в период с 23:00 17.08.2026 до 07:00 11.11.2026 (время московское) возможны перебои с доступом к сервису (Российская Федерация).", "В связи с проведением технологических работ на сервисе Подсистема ОИБ в период с 14:30 02.10.2026 до 15:30 02.10.2026 (время московское) возможны перебои с доступом к сервису (Ханты-Мансийский автономный округ - Югра)."], "d": "<p>Сервис предназначен для повышения уровня информационной поддержки и эффективности служебной деятельности сотрудников<br>ГУНК МВД России и подразделений по контролю за оборотом наркотиков территориальных органов МВД России при предоставлении государственных услуг</p>", "btn": ["Воспользоваться сервисом"], "docs": [["Основные документы", [["doc2", "Заявка на доступ", "23 января 2024, 10:11"], ["pdf", "Перечень ролей", "23 января 2024, 10:11"], ["pdf", "Приказ МВД России №984 от 21.12.23", "23 января 2024, 10:12"]]]], "resp": [["Тихонов Игорь Дмитриевич", "20 отдел (ОВИТвСЛОН УКЛОН ГУНК МВД России), Заместитель начальника отдела", "8 (495) 031-92-42", "itikhonov@mvd.ru"], ["Гусев Глеб Викторович", "4 отдел (ОООТО УКРКОН ГУНК МВД России), Старший оперуполномоченный по особо важным делам", "8 (495) 031-49-10", "ggusev80@mvd.ru"]], "nm": "^СОДП НК", "dx": ""}, {"id": 136, "n": "СОБТ", "t": "СОБТ", "tabs": ["Описание сервиса", "Вопросы по сервису"], "bc": 1, "al": ["В связи с проведением технологических работ на сервисе СУДИС в период с 23:00 17.08.2026 до 07:00 11.11.2026 (время московское) возможны перебои с доступом к сервису (Российская Федерация).", "В связи с проведением технологических работ на сервисе Подсистема ОИБ в период с 14:30 02.10.2026 до 15:30 02.10.2026 (время московское) возможны перебои с доступом к сервису (Ханты-Мансийский автономный округ - Югра)."], "d": "<p>Служебный сервис автоматизированного информационно-аналитического учета обеспечения безопасности на транспорте в составе ИСОД МВД России (СОБТ) является прикладным сервисом единой системы информационно-аналитического обеспечения деятельности МВД России по автоматизированному учету выданных заключений о допуске лиц к обеспечению транспортной безопасности и предназначен для обеспечения полного технологического цикла ввода, накопления, обработки и анализа оперативно-служебной информации в территориальных органах МВД России на транспорте, а также в специализированных подразделениях на федеральном уровне – ГУТ МВД России).<br>СОБТ представляет собой многопользовательскую информационную систему, информационно-технологическая структура которой соответствует административной структуре и объемам задач, возложенных на ОВДТ, включая ГУТ МВД России.</p>", "btn": ["Воспользоваться сервисом"], "docs": [["Последние обновленные документы", []]], "resp": [["Ершова Ольга Ивановна", "ОМВвСТБ ГУТ МВД России, Старший инспектор", "8 (495) 184-12-73", "oershova@mvd.ru"], ["Панфилова Елена Алексеевна", "ОМВвСТБ ГУТ МВД России, Старший инспектор по особым поручениям", "8 (495) 184-11-72", "epanfilova15@mvd.ru"]], "ts": 1, "nm": "^СОБТ", "dx": ""}, {"id": 143, "n": "СВПС", "t": "СВПС", "tabs": ["Описание сервиса"], "bc": 1, "al": ["В связи с проведением технологических работ на сервисе СУДИС в период с 23:00 17.08.2026 до 07:00 11.11.2026 (время московское) возможны перебои с доступом к сервису (Российская Федерация).", "В связи с проведением технологических работ на сервисе Подсистема ОИБ в период с 14:30 02.10.2026 до 15:30 02.10.2026 (время московское) возможны перебои с доступом к сервису (Ханты-Мансийский автономный округ - Югра)."], "d": "<p>Сервис ведомственной правовой статистики единой системы информационно-аналитического обеспечения деятельности Министерства внутренних дел Российской Федерации</p>", "btn": ["Воспользоваться сервисом"], "docs": [], "resp": [["Тарасова Полина Петровна", "ЦСИ ФКУ \"ГИАЦ МВД России\", Главный специалист отделения актуализации нормативно-справочной информации 3 отдела", "8 (495) 031-61-35", "itimokhina@mvd.ru"], ["Мельников Валентин Дмитриевич", "ЦСИ ФКУ \"ГИАЦ МВД России\", Инженер отделения актуализации нормативно-справочной информации 3 отдела", "8 (495) 031-51-16", "evolkov5@mvd.ru"]], "ts": 1, "nm": "^СВПС", "dx": ""}, {"id": 149, "n": "СОМПП", "t": "Сервис по обеспечению деятельности следственных подразделений в сфере оказания правовой помощи по уголовным делам", "tabs": ["Описание сервиса"], "al": ["В связи с проведением технологических работ на сервисе СУДИС в период с 23:00 17.08.2026 до 07:00 11.11.2026 (время московское) возможны перебои с доступом к сервису (Российская Федерация).", "В связи с проведением технологических работ на сервисе Подсистема ОИБ в период с 14:30 02.10.2026 до 15:30 02.10.2026 (время московское) возможны перебои с доступом к сервису (Ханты-Мансийский автономный округ - Югра)."], "d": "<p>СОМПП предназначен для обеспечения технической и информационной поддержки деятельности сотрудников Следственного департамента МВД России и следственных подразделений территориальных органов МВД России в сфере оказания правовой помощи по уголовным делам.</p><p>Основными функциями СОМПП являются:<br>1. Учет и систематизация поступающих и направляемых запросов об оказании правовой помощи по уголовным делам.<br>2. Контроль за исполнением поступающих и направляемых запросов об оказании правовой помощи по уголовным делам.<br>3. Выборка и сортировка запросов об оказании правовой помощи по уголовным делам по заданным параметрам.<br>4. Формирование отчетов по взаимодействию с компетентными органами иностранных государств в сфере оказания правовой помощи по уголовным делам.<br>5. Интеграция с сервисом электронного документооборота МВД России посредством операции «Экспорт РКФ», предназначенной для выгрузки документов и прикрепленных электронных образов.</p>", "btn": ["Воспользоваться сервисом"], "tr": ["Курсы по обучению \"СОМПП\""], "docs": [["Основные документы", [["pdf", "Описание программы", "22 июня 2023, 10:57"], ["pdf", "Приказ МВД России от 25 апреля 2023 г. № 253", "22 июня 2023, 10:57"], ["pdf", "Регламент эксплуатации СПО СОМПП", "22 июня 2023, 10:57"], ["pdf", "Руководство оператора", "22 июня 2023, 10:56"]]], ["Последние обновленные документы", []]], "resp": [["Чернов Вадим Михайлович", "", "", "vchernov@mvd.ru"]], "nm": "^СОМПП", "dx": ""}, {"id": 152, "n": "ЕИАС БДД", "t": "Единая информационно-аналитическая система БДД", "tabs": ["Описание сервиса"], "bc": 1, "d": "<p>ЕИАС БДД предназначена для обеспечения повседневных процессов деятельности сотрудников Госавтоинспекции по учёту, систематизации, обработке и хранению данных о дорожно-транспортных происшествиях, подготовке аналитической и официальной статистической информации в области обеспечения безопасности дорожного движения.</p><p>Средствами ЕИАС БДД автоматизированы следующие основные процессы:<br>1. Сбор, учёт, обработка и систематизация сведений о дорожно-транспортных происшествиях.<br>2. Формирование оперативной отчётности о состоянии дорожно-транспортной аварийности.<br>3. Формирование банков данных тематической информации, ассоциированной с учётом ДТП.<br>4. Ведение реестра образовательных организаций, мониторинг и контроль организационных мероприятий по пропаганде БДД среди учащихся.<br>5. Вынесение нижестоящим подразделениям Госавтоинспекции служебных поручений по компетенции и контроль их исполнения.<br>6. Формирование и публикация официальной статистической информации.<br>7. Подготовка показателей форм ведомственной и государственной статистической отчётности.<br>8. Публичное раскрытие сведений о состоянии безопасности дорожного движения на официальном сайте Госавтоинспекции.<br>9. Предоставление сведений о ДТП заинтересованным органам государственной власти.<br>10. Мониторинг, анализ и прогнозирование показателей аварийности.</p>", "btn": ["Воспользоваться сервисом"], "docs": [], "resp": [["Калинин Роман Михайлович", "3 отдел - ОРИТ ГУОБДД МВД России, Старший инспектор по особым поручениям", "8 (495) 184-07-93", "rkalinin@mvd.ru"]], "ts": 1, "nm": "ЕИАС БДД", "dx": ""}, {"id": 25, "n": "СЦУО", "t": "Сервис централизованного учета оружия", "tabs": ["Описание сервиса", "Вопросы по сервису", "Развитие сервиса"], "al": ["В связи с проведением технологических работ на сервисе СУДИС в период с 23:00 17.08.2026 до 07:00 11.11.2026 (время московское) возможны перебои с доступом к сервису (Российская Федерация).", "В связи с проведением технологических работ на сервисе Подсистема ОИБ в период с 14:30 02.10.2026 до 15:30 02.10.2026 (время московское) возможны перебои с доступом к сервису (Ханты-Мансийский автономный округ - Югра)."], "d": "<p>СЦУО - система централизованного учета нарезного боевого, служебного и гражданского оружия, гранатометов, реактивных пехотных огнеметов, переносных зенитно-ракетных и противотанковых комплексов на территории Российской Федерации и контроля за их оборотом. Сервис используется для решения задач сбора данных из различных источников, консолидации в единой информационной базе данных, представления сведений об учтенном в МВД России боевом, служебном и гражданском оружии и контроля за его перемещением в рамках подразделений МВД России.</p>", "btn": ["Воспользоваться сервисом"], "tr": ["Курс по обучению"], "docs": [["Основные документы", [["pdf", "Инструкция Администратора доступа", "18 июня 2015, 22:33"], ["pdf", "Инструкция пользователя", "27 августа 2015, 18:48"], ["pdf", "План внедрения сервиса СЦУО", "12 апреля 2015, 07:44"], ["pdf", "Презентация сервиса СЦУО", "27 августа 2015, 19:11"], ["pdf", "Руководство администратора", "27 августа 2015, 18:47"]]]], "resp": [["Зорин Глеб Юрьевич", "Инспектор", "8 (495) 622-33-25", "gzorin2@mvd.ru"], ["Лаптева Мария Владимировна", "", "", ""]], "nm": "^СЦУО", "dx": ""}];
const SVC_SID={"СВКС-м": 3, "СЭД": 2, "ВИСП": 5, "Интернет-сайт": 6, "СОДП СБ": 7, "ЕАИС ЭКП": 8, "Контроль за оборотом наркотиков": 9, "СОБТ": 10, "СВПС": 11, "СОМПП": 12, "ЕИАС БДД": 13, "СЦУО": 14};
